INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Rocket_Jump', 'Rocket Jump', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body. To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.'),
('Rocking_Standing_Calf_Raise', 'Rocking Standing Calf Raise', 'legs', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoul'),
('Rocky_Pull-Ups_Pulldowns', 'Rocky Pull-Ups/Pulldowns', 'back', ARRAY['arms','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on'),
('Romanian_Deadlift', 'Romanian Deadlift', 'legs', ARRAY['legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion. Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position. Keeping your back and arms completely straight at all times, use your hips to lift th'),
('Romanian_Deadlift_from_Deficit', 'Romanian Deadlift from Deficit', 'legs', ARRAY['arms','legs','back','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion. Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings. Reverse the motion to retu'),
('Rope_Climb', 'Rope Climb', 'back', ARRAY['arms','arms','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Grab the rope with both hands above your head. Pull down on the rope as you take a small jump. Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly. Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest. Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope. To lower yourself, lo'),
('Rope_Crunch', 'Rope Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Kneel 1-2 feet in front of a cable system with a rope attached. After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position. To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down. Pause at the bottom of the motion, and then slowly return to the starting position. These can be done with twists or to the side to hit the obliques.'),
('Rope_Jumping', 'Rope Jumping', 'legs', ARRAY['legs','legs']::text[], 'other', 'cardio', 'intermediate', 'Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation. Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to o'),
('Rope_Straight-Arm_Pulldown', 'Rope Straight-Arm Pulldown', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position. Keeping your arms straight, extend the shoulder to pull the rope down to your thighs. Pause at the bottom of the motion, squeezing your lats. Return to the starting position without allowing the weigh'),
('Round_The_World_Shoulder_Stretch', 'Round The World Shoulder Stretch', 'shoulders', ARRAY['arms','chest']::text[], 'other', 'stretching', 'beginner', 'Stand up straight with your legs together, holding a bodybar or broomstick. Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out. Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further.'),
('Rowing_Stationary', 'Rowing, Stationary', 'legs', ARRAY['arms','legs','legs','legs','back','back']::text[], 'machine', 'cardio', 'intermediate', 'To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips. There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next,'),
('Runners_Stretch', 'Runner''s Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor. Keep the front heel on the floor (if it lifts up, scoot your other leg further back). Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.'),
('Running_Treadmill', 'Running, Treadmill', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'beginner', 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour f'),
('Russian_Twist', 'Russian Twist', 'core', ARRAY['back']::text[], 'bodyweight', 'strength', 'intermediate', 'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees. Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position. Twist your torso to the right side until your arms are parallel with the floor while breathing out. Hold the contraction for '),
('Sandbag_Load', 'Sandbag Load', 'legs', ARRAY['core','arms','legs','arms','legs','legs','back','back','shoulders','back']::text[], 'other', 'strongman', 'beginner', 'To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet. Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankl'),
('Scapular_Pull-Up', 'Scapular Pull-Up', 'back', ARRAY['back','back']::text[], 'other', 'strength', 'beginner', 'Take a pronated grip on a pull-up bar. From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion. Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.'),
('Scissor_Kick', 'Scissor Kick', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time. With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position. Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground. Swi'),
('Scissors_Jump', 'Scissors Jump', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground. Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift. As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front. As you land, absorb the impact through the legs by adopting the lunge position, and repeat.'),
('Seated_Band_Hamstring_Curl', 'Seated Band Hamstring Curl', 'legs', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Secure a band close to the ground and place a bench a couple feet away from it. Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position. Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor. Pause at the completion of the movement, and then slowly return to the starting position.'),
('Seated_Barbell_Military_Press', 'Seated Barbell Military Press', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about sho'),
('Seated_Barbell_Twist', 'Seated Barbell Twist', 'core', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other. Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended. Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position. While keeping your feet and hea'),
('Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold'),
('Seated_Bent-Over_Rear_Delt_Raise', 'Seated Bent-Over Rear Delt Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Place a couple of dumbbells looking forward in front of a flat bench. Sit on the end of the bench with your legs together and the dumbbells behind your calves. Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position. Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are par'),
('Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the han'),
('Seated_Biceps', 'Seated Biceps', 'arms', ARRAY['chest','shoulders']::text[], 'bodyweight', 'stretching', 'expert', 'Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position. Attempt to flex your elbows, while your partner prevents any actual movement. After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or '),
('Seated_Cable_Rows', 'Seated Cable Rows', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the V-bar handles. With your arms extended pull back until yo'),
('Seated_Cable_Shoulder_Press', 'Seated Cable Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together above your head. After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables. You can also execute this movement with yo'),
('Seated_Calf_Raise', 'Seated Calf Raise', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter. Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward. Lift the lever slightly by pushing your heels up and release the safety bar.'),
('Seated_Calf_Stretch', 'Seated Calf Stretch', 'legs', ARRAY['legs','back']::text[], 'other', 'stretching', 'beginner', 'Sit up straight on an exercise mat. Bend one knee and put that foot on the floor to stabilize the torso. Straighten your other leg and flex your ankle. Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides.'),
('Seated_Close-Grip_Concentration_Barbell_Curl', 'Seated Close-Grip Concentration Barbell Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor. Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floo'),
('Seated_Dumbbell_Curl', 'Seated Dumbbell Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing your torso. This will be your starting position. While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only th'),
('Seated_Dumbbell_Inner_Biceps_Curl', 'Seated Dumbbell Inner Biceps Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips: Only the forearms should move. Continue the movement until your biceps are full'),
('Seated_Dumbbell_Palms-Down_Wrist_Curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists bac'),
('Seated_Dumbbell_Palms-Up_Wrist_Curl', 'Seated Dumbbell Palms-Up Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back '),
('Seated_Dumbbell_Press', 'Seated Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs. Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. This is your starting position. As you exhale, push the dumbbells up until they touch at the top. After a second pause, slowly come down back to '),
('Seated_Flat_Bench_Leg_Pull-In', 'Seated Flat Bench Leg Pull-In', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position. Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Seated_Floor_Hamstring_Stretch', 'Seated Floor Hamstring Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh. Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side.'),
('Seated_Front_Deltoid', 'Seated Front Deltoid', 'shoulders', ARRAY['chest']::text[], 'bodyweight', 'stretching', 'expert', 'Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position. Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds. Now, relax your muscles and allow your partner to gent'),
('Seated_Glute', 'Seated Glute', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'expert', 'In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position. Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso. Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.'),
('Seated_Good_Mornings', 'Seated Good Mornings', 'back', ARRAY['legs']::text[], 'barbell', 'powerlifting', 'intermediate', 'Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your '),
('Seated_Hamstring', 'Seated Hamstring', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'expert', 'In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position. Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso. Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.'),
('Seated_Hamstring_and_Calf_Stretch', 'Seated Hamstring and Calf Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'intermediate', 'Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position. Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg.'),
('Seated_Head_Harness_Neck_Resistance', 'Seated Head Harness Neck Resistance', 'other', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out. Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands whi'),
('Seated_Leg_Curl', 'Seated Leg Curl', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad. Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position. As y'),
('Seated_Leg_Tucks', 'Seated Leg Tucks', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position. Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement. Now curl the dumbbell as h'),
('Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement. Now curl the dumbbell as hi'),
('Seated_One-arm_Cable_Pulley_Rows', 'Seated One-arm Cable Pulley Rows', 'back', ARRAY['arms','back','back']::text[], 'cable', 'strength', 'intermediate', 'To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip. With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You sh'),
('Seated_Overhead_Stretch', 'Seated Overhead Stretch', 'core', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Sit up straight on an exercise mat. Touch the soles of your feet together with your feet six to eight inches in front of your hips. Place one hand on the floor beside you and your other hand behind your head. Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides.'),
('Seated_Palm-Up_Barbell_Wrist_Curl', 'Seated Palm-Up Barbell Wrist Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip. Now curl bar up as high as possible while f')
